61	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
62	// branch is disconnected and prints a warning to stderr if so.
63	// It does NOT fix the problem — users are directed to 'entire doctor'.
64	//
65	// Uses sync.Once, so a transient failure on the first call permanently suppresses
66	// the warning. This is acceptable because the check is advisory only and
67	// 'entire doctor' is the authoritative repair path.
68	func WarnIfMetadataDisconnected() {
69		disconnectedOnce.Do(func() {
70			ctx := context.Background()
71			repo, err := OpenRepository(ctx)
72			if err != nil {
73				logging.Debug(ctx, "metadata disconnection check: could not open repository",
74					slog.String("error", err.Error()))
75				return
76			}
77			disconnected, err := IsMetadataDisconnected(ctx, repo, plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName))
78			if err != nil {
79				logging.Debug(ctx, "metadata disconnection check failed",
80					slog.String("error", err.Error()))
81				return
82			}
83			if !disconnected {
84				return
85			}
86			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
87			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
88		})
