91	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
92	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
93	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
94	// and handled by the push path's tree merge.
95	//
96	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
97	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
98	// apply cleanly.
99	//
100	// Progress messages are written to w (typically os.Stderr for hooks or
101	// cmd.ErrOrStderr() for commands).
102	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
103	func ReconcileDisconnectedMetadataBranch(
104		ctx context.Context,
105		repo *git.Repository,
106		remoteRefName plumbing.ReferenceName,
107		w io.Writer,
108	) error {
109		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
110	
111		// Check local branch
112		localRef, err := repo.Reference(refName, true)
113		if errors.Is(err, plumbing.ErrReferenceNotFound) {
114			return nil // No local branch — nothing to reconcile
115		}
116		if err != nil {
117			return fmt.Errorf("failed to check local metadata branch: %w", err)
118		}
119	
120		// Check remote-tracking branch
121		remoteRef, err := repo.Reference(remoteRefName, true)
122		if errors.Is(err, plumbing.ErrReferenceNotFound) {
123			return nil // No remote branch — nothing to reconcile
124		}
125		if err != nil {
126			return fmt.Errorf("failed to check remote metadata branch: %w", err)
127		}
128	
129		localHash := localRef.Hash()
130		remoteHash := remoteRef.Hash()
131	
132		// Same hash — nothing to do
133		if localHash == remoteHash {
