package strategy

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

var (
	cherryPickBenchRepoPath = flag.String(
		"cherrypick-bench-repo",
		"~/git/entireio/cli-checkpoints",
		"path to the large checkpoints repository used by BenchmarkCherryPickOntoLargeRepository",
	)
	cherryPickBenchCommitCount = flag.Int(
		"cherrypick-bench-commits",
		20,
		"number of commits to stage and replay in BenchmarkCherryPickOntoLargeRepository",
	)
	cherryPickBenchSourceOffset = flag.Int(
		"cherrypick-bench-source-offset",
		1000,
		"first-parent distance from entire/checkpoints/v1 HEAD of the oldest source commit",
	)
)

// BenchmarkCherryPickOntoLargeRepository measures cherryPickOnto against a real,
// large metadata repository. It intentionally skips when the repo is absent so
// normal test runs do not need this local fixture.
//
// Example:
//
//	go test ./cmd/entire/cli/strategy -run '^$' -bench '^BenchmarkCherryPickOntoLargeRepository$' -benchmem -args -cherrypick-bench-commits=200
func BenchmarkCherryPickOntoLargeRepository(b *testing.B) {
	ctx := context.Background()
	count := *cherryPickBenchCommitCount
	if count <= 0 {
		b.Fatalf("-cherrypick-bench-commits must be greater than zero, got %d", count)
	}
	sourceOffset := *cherryPickBenchSourceOffset
	if sourceOffset < 0 {
		b.Fatalf("-cherrypick-bench-source-offset must be non-negative, got %d", sourceOffset)
	}
	if sourceOffset < count-1 {
		b.Fatalf("-cherrypick-bench-source-offset must be at least commits-1 so the source range can move toward HEAD")
	}
	sourceTipOffset := sourceOffset - count + 1

	repoPath, err := expandCherryPickBenchPath(*cherryPickBenchRepoPath)
	if err != nil {
		b.Fatalf("resolve benchmark repo path: %v", err)
	}
	if _, err := os.Stat(repoPath); err != nil {
		if os.IsNotExist(err) {
			b.Skipf("benchmark repo %q does not exist", repoPath)
		}
		b.Fatalf("stat benchmark repo %q: %v", repoPath, err)
	}

	repo, err := git.PlainOpenWithOptions(repoPath, &git.PlainOpenOptions{DetectDotGit: true})
	if err != nil {
		b.Skipf("open benchmark repo %q: %v", repoPath, err)
	}

	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		b.Skipf("benchmark repo %q does not have branch %s: %v", repoPath, paths.MetadataBranchName, err)
	}
	defaultHead := defaultRef.Hash()
	baseCommit := firstParentCommitAtDepth(b, repo, defaultHead, count, "base branch")
	sourceCommits := firstParentCommitSegment(b, repo, defaultHead, sourceTipOffset, count, "source commits")
	requireNonMergeBenchCommits(b, sourceCommits, "source commits")

	branchPrefix := fmt.Sprintf("entire-bench/cherry-pick-%d-%d", os.Getpid(), time.Now().UnixNano())
	var cleanupRefs []plumbing.ReferenceName
	b.Cleanup(func() {
		cleanupCherryPickBenchRefs(b, repo, cleanupRefs)
	})

	baseRefName := trackCherryPickBenchRef(&cleanupRefs, branchPrefix+"/base")
	setCherryPickBenchRef(b, repo, baseRefName, baseCommit.Hash)

	workingTip, err := cherryPickOnto(ctx, repo, baseCommit.Hash, sourceCommits)
	if err != nil {
		b.Fatalf("setup cherryPickOnto onto working branch: %v", err)
	}
	workingRefName := trackCherryPickBenchRef(&cleanupRefs, branchPrefix+"/working")
	setCherryPickBenchRef(b, repo, workingRefName, workingTip)

